function HighlightTemplateText({ text }: { text: string }) {
  return <>{text.split(/(\[\[[^\]]+\]\])/g).map((part, index) => part.startsWith("[[") ? <mark key={`${part}-${index}`} className="kairema-template-placeholder">{part.slice(2, -2)}</mark> : <span key={`text-${index}`}>{part}</span>)}</>;
}

function PromptTemplatesDialog({ open, onOpenChange, onInsert, onCopy }: { open: boolean; onOpenChange: (open: boolean) => void; onInsert: (template: PromptTemplate) => void; onCopy: (template: PromptTemplate) => void }) {
  return <Dialog open={open} onOpenChange={onOpenChange}><DialogContent className="kairema-dialog kairema-dialog-wide"><DialogHeader><DialogTitle>Шаблоны промптов</DialogTitle></DialogHeader><p className="kairema-dialog-note">Выберите основу для запроса. Поля с цветной подсветкой замените своими деталями.</p><div className="kairema-template-grid">{PROMPT_TEMPLATES.map((template) => <article className={`kairema-template-card kairema-template-${template.accent}`} key={template.id}><div><span className="kairema-template-category">{template.category}</span><h3>{template.title}</h3><p>{template.description}</p></div><p className="kairema-template-text"><HighlightTemplateText text={template.text} /></p><div className="kairema-template-actions"><button type="button" onClick={() => onCopy(template)}><Copy className="size-3.5" />Копировать</button><button type="button" className="kairema-template-insert" onClick={() => onInsert(template)}><Sparkles className="size-3.5" />Вставить в запрос</button></div></article>)}</div></DialogContent></Dialog>;
}

function statusClass(status?: PublicStatus) { return status?.state === "ready" || status?.state === "fallback" ? "status-ready" : status?.category === "RATE_LIMIT" || status?.category === "QUOTA" ? "status-quota" : status?.state === "not_configured" ? "status-muted" : status?.state === "unavailable" ? "status-unavailable" : status?.state === "loading" ? "status-loading" : "status-auth"; }
function StatusIndicator({ status }: { status?: PublicStatus }) { const label = status?.badge ?? "…"; const Icon = status?.state === "ready" ? CircleCheck : status?.category === "RATE_LIMIT" || status?.category === "QUOTA" ? Gauge : status?.state === "loading" || !status ? LoaderCircle : TriangleAlert; return <span className={`kairema-status ${statusClass(status)}`} title={status?.confirmed ?? label}><Icon className={`size-3 ${status?.state === "loading" || !status ? "animate-spin" : ""}`} /><span>{label}</span></span>; }
function bytes(value: number) { return value < 1_000_000 ? `${Math.max(1, Math.round(value / 1024))} KB` : `${(value / 1_000_000).toFixed(1)} MB`; }
function metadataSources(metadata: unknown): Source[] | undefined { try { const parsed = typeof metadata === "string" ? JSON.parse(metadata) : metadata; const web = Array.isArray(parsed?.sources) ? parsed.sources.filter((item): item is Source => typeof item?.title === "string" && typeof item?.url === "string").map((item) => ({ ...item, kind: "web" as const })) : []; const rag = Array.isArray(parsed?.ragSources) ? parsed.ragSources.filter((item): item is Source => typeof item?.title === "string" && typeof item?.url === "string").map((item) => ({ ...item, kind: "rag" as const, publishedAt: typeof item.publishedAt === "string" ? item.publishedAt : null })) : []; return [...web, ...rag].length ? [...web, ...rag] : undefined; } catch { return undefined; } }
function dataUrlContent(file: File) { return new Promise<string>((resolve, reject) => { const reader = new FileReader(); reader.onerror = () => reject(reader.error); reader.onload = () => resolve(String(reader.result).split(",")[1] ?? ""); reader.readAsDataURL(file); }); }
function contentType(file: File) { if (file.type === "image/png" || file.type === "image/jpeg" || file.type === "image/webp" || file.type === "application/pdf" || file.type === "text/plain" || file.type === "text/markdown") return file.type; return file.name.toLowerCase().endsWith(".md") ? "text/markdown" : null; }
function errorPayloadMessage(value: unknown): string | null {
  if (typeof value === "string" && value.trim()) return value.trim();
  if (!value || typeof value !== "object") return null;
  const record = value as Record<string, unknown>;
  return errorPayloadMessage(record.message) ?? errorPayloadMessage(record.error) ?? errorPayloadMessage(record.detail);
}
function publicErrorMessage(error: unknown, fallback: string): string {
  return error instanceof Error && error.message.trim() ? error.message.trim() : errorPayloadMessage(error) ?? fallback;
}
async function streamStartErrorMessage(response: Response, fallback: string): Promise<string> {
  const body = await response.text().catch(() => "");
  if (!body) return fallback;
  try {
    return errorPayloadMessage(JSON.parse(body)) ?? fallback;
  } catch {
    return fallback;
  }
}

